// Determine quelles offres doivent etre relancees et a quel palier
const offres = $('Offres en Attente').all().map(i => i.json);
const relancesExistantes = $('Relances Deja Envoyees').all().map(i => i.json);

const now = new Date();
const results = [];

// Index des relances existantes: offre_id -> Set de paliers
const relancesIndex = {};
for (const r of relancesExistantes) {
  if (!relancesIndex[r.offre_id]) relancesIndex[r.offre_id] = new Set();
  relancesIndex[r.offre_id].add(r.palier);
}

// Paliers de relance (jours avant expiration)
const paliers = [
  { jours: 30, palier: 'J-30' },
  { jours: 15, palier: 'J-15' },
  { jours: 7,  palier: 'J-7' },
  { jours: 1,  palier: 'J-1' }
];

for (const offre of offres) {
  if (!offre.date_expiration) continue;

  const dateExp = new Date(offre.date_expiration);
  const joursRestants = Math.ceil((dateExp - now) / (1000 * 60 * 60 * 24));

  // Trouver le palier applicable (tolerance ±2 jours)
  for (const p of paliers) {
    if (joursRestants >= p.jours - 2 && joursRestants <= p.jours + 2) {
      // Anti-doublon
      if (relancesIndex[offre.id]?.has(p.palier)) continue;

      results.push({
        json: {
          offre_id: offre.id,
          reference_offre: offre.reference_offre,
          entreprise_id: offre.entreprise_id,
          montant_ht: offre.montant_ht,
          date_offre: offre.date_offre,
          date_expiration: offre.date_expiration,
          correspondant: offre.correspondant,
          fichier_source: offre.fichier_source,
          jours_restants: joursRestants,
          palier: p.palier
        }
      });
      break;
    }
  }
}

if (results.length === 0) {
  return [{ json: { _no_relances: true } }];
}

return results;

// Remplace les variables {{...}} dans le template HTML
const offre = $('Relances a envoyer ?').first().json;
const entreprise = $('Recuperer Entreprise').first().json;
const template = $('Recuperer Template').first().json;

// Config expediteur (a ajuster selon config client)
const expediteur = {
  nom: 'Alice Durand',
  titre: 'Assistante administration des ventes',
  email: 'alice.durand@thermopack.example',
  tel: '01 60 86 10 25'
};

// URL webhook opt-out (WF-003b)
const N8N_BASE = 'https://n8n.example.com';
const lienStopRelance = `${N8N_BASE}/webhook/thermopack/stop-relance?offre_id=${offre.offre_id}&ref=${encodeURIComponent(offre.reference_offre)}`;

// Formater montant
const montantFormate = new Intl.NumberFormat(entreprise.pays === 'ES' ? 'es-ES' : 'fr-FR', {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2
}).format(offre.montant_ht || 0);

// Formater date
const dateExp = new Date(offre.date_expiration);
const dateFormatee = dateExp.toLocaleDateString(entreprise.pays === 'ES' ? 'es-ES' : 'fr-FR', {
  day: '2-digit', month: 'long', year: 'numeric'
});

// Nom contact avec fallback
const nomContact = entreprise.contact_nom || (entreprise.pays === 'ES' ? 'Estimado/a cliente' : 'Madame, Monsieur');

// Remplacement des variables
let html = template.corps_html;
let objet = template.objet;

const vars = {
  '{{nom_contact}}': nomContact,
  '{{entreprise}}': entreprise.nom,
  '{{reference_offre}}': offre.reference_offre,
  '{{montant_ht}}': montantFormate,
  '{{date_expiration}}': dateFormatee,
  '{{jours_restants}}': String(offre.jours_restants),
  '{{expediteur_nom}}': expediteur.nom,
  '{{expediteur_titre}}': expediteur.titre,
  '{{expediteur_email}}': expediteur.email,
  '{{tel}}': expediteur.tel,
  '{{lien_stop_relance}}': lienStopRelance
};

for (const [key, val] of Object.entries(vars)) {
  html = html.split(key).join(val);
  objet = objet.split(key).join(val);
}

const destinataire = entreprise.contact_email;
if (!destinataire) {
  throw new Error(`Pas d'email pour ${entreprise.nom} (id: ${entreprise.id})`);
}

return [{
  json: {
    offre_id: offre.offre_id,
    reference_offre: offre.reference_offre,
    entreprise_nom: entreprise.nom,
    palier: offre.palier,
    email_destinataire: destinataire,
    email_sujet: objet,
    email_html: html,
    pays: entreprise.pays || 'FR',
    expediteur_email: expediteur.email
  }
}];

// Prepare le log de relance (succes ou erreur)
const data = $input.first().json;
const relanceData = $('Injecter Variables Template').first().json;

const isError = !!data.error || !!data.errorMessage;

return [{
  json: {
    offre_id: relanceData.offre_id,
    reference_offre: relanceData.reference_offre,
    entreprise_nom: relanceData.entreprise_nom,
    palier: relanceData.palier,
    email_destinataire: relanceData.email_destinataire,
    email_sujet: relanceData.email_sujet,
    statut: isError ? 'erreur' : 'envoye',
    erreur: isError ? JSON.stringify(data).substring(0, 500) : null
  }
}];
